def decompressFromBase64(compressed):
    """LZ-String decompressFromBase64 实现"""

    # LZ-String 的 Base64 字符集
    keyStr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/="

    # 首先进行自定义 base64 解码（lz-string 使用修改的 base64）
