    # 从位流中读取
    class BitReader:
        def __init__(self, bits):
            self.bits = bits
            self.pos = 0

        def read(self, n):
            result = 0
            for i in range(n):
                result = (result << 1) | int(self.bits[self.pos])
                self.pos += 1
            return result

